// Home's Since you were away card (spec F2): what happened since the user last
// marked it read (the page's `t`, localStorage home.since in public/since.js),
// as at most eight one-fact lines. Nothing here is
// generated by a model: every line is a count or a change the server already
// has.
//
//   flows       `Add a dark mode toggle is done`    a flow whose status changed (flows-prev.json)
//   deliveries  `2 answers delivered, 1 not delivered`    asks sent, or failed, since then
//   levels      `ABC-101 moved to Stage`          the orchestration level went up (levels-prev.json)
//   tickets     `ABC-103 changed on Switchboard: In Progress → In Review`    (sources/<id>.prev.json)
//   commits     `Agent 1 committed 3 times on ABC-102`    git, per agent worktree
//
// That order is the priority: the cap of MAX_LINES keeps flows first and cuts
// commits first. sinceDigest is pure; sinceRoute (factory-routes.mjs) gathers
// its inputs. The change records, and why they are notes and not copies, are
// in since-store.mjs.
//
// ⚠️ The text of a line is RAW (a flow title is whatever an agent wrote): the
// page escapes it (public/since.js).

import { readLevels, readLevelsPrev, readFlowsPrev, readSourcePrev } from './since-store.mjs'
import { idsInText } from './transcripts.mjs'

export const MAX_LINES = 8
const LEVEL_NAME = { local: 'Local', dev: 'Dev', stage: 'Stage', prod: 'Prod' }
const ORDER = ['flows', 'deliveries', 'levels', 'tickets', 'commits']
/** A source state as the Tickets page shows it (factory.mjs buildFactory). */
const stateName = s => (!s || s === 'None' ? 'Unstarted' : String(s))
const times = n => (n === 1 ? 'once' : `${n} times`)
const answers = n => `${n} ${n === 1 ? 'answer' : 'answers'}`
const ms = iso => (typeof iso === 'string' && iso ? Date.parse(iso) : NaN)
const newestFirst = (a, b) => (ms(b.at) || 0) - (ms(a.at) || 0)
/** The later of two times, as given (commit dates carry an offset, so compare as numbers). */
const later = (a, b) => (!a || ms(b) > ms(a) ? b : a)

/** The empty digest: what a future or unparsable baseline gets. */
export const emptyDigest = (since = null) => ({ since, commits: [], levels: [], flows: [], deliveries: [], tickets: [] })

/** The baseline time as a number, or NaN when it is not a time or lies in the future. */
export function sinceTime(since, now = Date.now()) {
  const t = ms(since)
  return t <= now ? t : NaN
}

/**
 * Pure. Each input is optional:
 *   commits      [{ sha, date, subject, agent, branch }]   (gatherCommits)
 *   levels       { ticketId: level }, levelsPrev { ticketId: { level, at } }
 *   flows        the flow files (listFlows), flowsPrev { flowId: { status, at } }
 *   sources      [{ id, label, tickets: { ID: { state } } }], sourcesPrev { id: { tickets: { ID: { state, at } } } }
 * Returns { since, flows, deliveries, levels, tickets, commits }: arrays of
 * { text, href, at, ticket?, flow? }, at most MAX_LINES in all, in that priority.
 */
export function sinceDigest({ since, now = Date.now(), commits = [], levels = {}, levelsPrev = {}, flows = [], flowsPrev = {}, sources = [], sourcesPrev = {} } = {}) {
  const t = sinceTime(since, now)
  if (Number.isNaN(t)) return emptyDigest(null)
  const after = iso => ms(iso) > t
  const all = {
    flows: flowLines(flows, flowsPrev, after),
    deliveries: deliveryLines(flows, after),
    levels: levelLines(levels, levelsPrev, after),
    tickets: ticketLines(sources, sourcesPrev, after),
    commits: commitLines(commits, after),
  }
  const out = emptyDigest(since)
  let room = MAX_LINES
  for (const k of ORDER) {
    out[k] = all[k].slice(0, room)
    room -= out[k].length
  }
  return out
}

function flowLines(flows, prev, after) {
  const lines = []
  for (const f of flows) {
    const note = prev[f.id]
    if (!note || !after(note.at) || note.status === f.status) continue
    lines.push({ text: `${f.title} is ${f.status}`, href: '#/flows', flow: f.id, at: note.at })
  }
  return lines.sort(newestFirst)
}

/**
 * Asks sent since then, and asks whose push failed in a write since then
 * (a deliveryError carries no time of its own; the flow's updatedAt is the
 * write that recorded it). One line, linked to the flow when only one is involved.
 */
function deliveryLines(flows, after) {
  let sent = 0
  let failed = 0
  let at = ''
  const involved = new Set()
  for (const f of flows) {
    for (const n of f.nodes || []) {
      if (n.type !== 'ask') continue
      if (n.sentAt && after(n.sentAt)) {
        sent++
        involved.add(f.id)
        at = later(at, n.sentAt)
      } else if (n.deliveryError != null && after(f.updatedAt)) {
        failed++
        involved.add(f.id)
        at = later(at, f.updatedAt)
      }
    }
  }
  if (!sent && !failed) return []
  const text = sent && failed ? `${answers(sent)} delivered, ${failed} not delivered` : sent ? `${answers(sent)} delivered` : `${answers(failed)} not delivered`
  const line = { text, href: '#/flows', at }
  if (involved.size === 1) line.flow = [...involved][0]
  return [line]
}

function levelLines(levels, prev, after) {
  const lines = []
  for (const [id, note] of Object.entries(prev)) {
    const now = levels[id]
    if (!now || !after(note?.at) || note.level === now) continue
    lines.push({ text: `${id} moved to ${LEVEL_NAME[now] || now}`, href: '#/tickets', ticket: id, at: note.at })
  }
  return lines.sort(newestFirst)
}

function ticketLines(sources, prev, after) {
  const lines = []
  const seen = new Set()
  for (const src of sources) {
    for (const [id, note] of Object.entries(prev[src.id]?.tickets || {})) {
      const cur = src.tickets?.[id]
      if (!cur || seen.has(id) || !after(note?.at) || stateName(note.state) === stateName(cur.state)) continue
      seen.add(id)
      lines.push({ text: `${id} changed on ${src.label}: ${stateName(note.state)} → ${stateName(cur.state)}`, href: '#/tickets', ticket: id, at: note.at })
    }
  }
  return lines.sort(newestFirst)
}

/**
 * Commits after the baseline, grouped by agent and ticket. A commit counts once
 * (the same sha on an agent branch and on followup, or naming two tickets: it
 * goes to the FIRST ticket it names); one naming no ticket is not listed.
 */
function commitLines(commits, after) {
  const groups = new Map()
  const seen = new Set()
  for (const c of commits) {
    if (!c?.sha || seen.has(c.sha) || !after(c.date)) continue
    const ticket = idsInText(c.subject || '')[0]
    if (!ticket) continue
    seen.add(c.sha)
    const key = `${c.agent}|${ticket}`
    const g = groups.get(key) || { agent: c.agent, ticket, n: 0, at: '' }
    g.n++
    g.at = later(g.at, c.date)
    groups.set(key, g)
  }
  return [...groups.values()]
    .sort(newestFirst)
    .map(g => ({ text: `${g.agent} committed ${times(g.n)} on ${g.ticket}`, href: '#/tickets', ticket: g.ticket, at: g.at }))
}

// ═══ gathering the inputs (the route) ═══

/**
 * Every commit after `since` that each worktree an agent owns ADDED (the
 * /api/status build's `worktrees`, with their `agent` label): agent worktrees
 * first, so a commit Coordinator merged onto followup counts for the agent that
 * wrote it. Merges are left out. `git(args)` resolves { ok, out } like server.mjs's.
 * ⚠️ `origin/dev..<branch>`, never the bare branch (as localWork in
 * orchestration.mjs): every branch starts from dev and followup merges dev in,
 * so a bare log reaches every commit that landed on dev, and the first agent
 * walked would be credited with all of them.
 */
export async function gatherCommits({ git, status, since }) {
  const trees = (status?.worktrees || []).filter(w => w.agent && w.branch && w.branch !== '(detached)')
  trees.sort((a, b) => Number(Boolean(b.isAgentTree)) - Number(Boolean(a.isAgentTree)))
  const runs = await Promise.all(trees.map(w => git(['log', `origin/dev..${w.branch}`, '--no-merges', `--since=${since}`, '--format=%h%x09%cI%x09%s', '--'])))
  const out = []
  runs.forEach((r, i) => {
    if (!r?.ok) return
    for (const line of r.out.split('\n')) {
      const [sha, date, subject = ''] = line.split('\t')
      if (sha && date) out.push({ sha, date, subject, agent: trees[i].agent, branch: trees[i].branch })
    }
  })
  return out
}

/**
 * The digest for GET /api/since?t=<ISO>. A future or unparsable `t` is the
 * empty digest, with no git or status work. A status build that fails only
 * costs the commit lines.
 * `deps`: { git, getStatus, listFlows, collections, readSource }.
 */
export async function sinceRoute(t, { git, getStatus, listFlows, collections, readSource }) {
  const time = sinceTime(t)
  if (Number.isNaN(time)) return emptyDigest(null)
  const since = new Date(time).toISOString() // what git gets: a normalised time, never the raw query text
  let commits = []
  try {
    commits = await gatherCommits({ git, status: await getStatus(false), since })
  } catch {
    commits = []
  }
  const cols = collections()
  return sinceDigest({
    since,
    commits,
    levels: readLevels(),
    levelsPrev: readLevelsPrev(),
    flows: listFlows().flows,
    flowsPrev: readFlowsPrev(),
    sources: cols.map(c => ({ id: c.id, label: c.kind === 'switchboard' ? 'Switchboard' : c.name, tickets: readSource(c.id)?.tickets || {} })),
    sourcesPrev: Object.fromEntries(cols.map(c => [c.id, readSourcePrev(c.id)]).filter(([, p]) => p)),
  })
}
